function mostrarTaset(codi, tipus) {
	if (!$('#veure_tastet_'+codi)[0]) {
		$.ajax({
			url: "https://www.prisma.cat/ajax/mostrar_tastet.php?dispositiu=" + dispositiu + "&codi=" + codi+"&tipus=" + tipus,
			cache: !1,
			type: "GET",
			success: function(tastet) {
				$("#home").append(tastet);

				//Mostrar el video de la presentacio del curs quan cliques la caratula
				var video  = $('#veure_tastet_'+codi+" .video-responsive");
				video.on("click", function(){
					var obj = $(this);
					$(this).find('iframe')[0].src=$(this).find('iframe')[0].src.replace("autoplay=0", "autoplay=1");
					setTimeout(function(){
						obj.find('button').hide();
						obj.find('img').hide();
					},500);
				});

				//Pausar el video quan surts del modal de veure un tastet
				$('#veure_tastet_'+codi).on('hide.bs.modal', function (e) {
					if ($(this).find('iframe')[0]) {
						var src= $(this).find('iframe')[0].src;
						$(this).find('iframe')[0].src = src;
						$(this).find('iframe')[0].src = src.replace("autoplay=1", "autoplay=0");
						$(this).find('img').show();
						$(this).find('button').show();
					}
				});

				//Pausar el video de presentacioq quan s'obre un modal
				$('#veure_tastet_'+codi).on('show.bs.modal ', function (e) {
					if ($('#video-presentacio iframe')[0]) {
					  var src= $('#video-presentacio iframe')[0].src;
					  $('#video-presentacio iframe')[0].src = src;
					  $('#video-presentacio iframe')[0].src = src.replace("autoplay=1", "autoplay=0");
					  $('#video-presentacio').find('img').show();
					  $('#video-presentacio').find('button').show();
				  }

				  //En cas que hi hagi spot, pausem el video del spot
				  if ($('.cnt-spot .video-responsive').find('iframe')[0])
				  	$('.cnt-spot .video-responsive').find('iframe')[0].src =  $('.cnt-spot .video-responsive').find('iframe')[0].src.replace("autoplay=1", "autoplay=0");
				});
				$('#veure_tastet_'+codi).modal('show');

			}
		})
	}
	else {
		$('#veure_tastet_'+codi).modal('show');
	}

}

/* Quan es clica un element del desplegable, es canvia l'orientació de les fletxes*/
function toogleLlistat(e, idThis) {
	e.stopPropagation();
	var lista = $('#'+idThis).find("ul"),
		triangle = $('#'+idThis).find("i");
	e.preventDefault();
	$('#'+idThis).find("ul").toggle();
	if (lista.is(":hidden")) {
		triangle.removeClass("fa-angle-up").addClass("fa-angle-down");
	} else {
		triangle.removeClass("fa-angle-down").addClass("fa-angle-up");
	}
};

/* Quan cliquen una opció del desplegable d'ordenacions o d'edicions,
	si es el filtre d'edicions, s'afegeix en el filtre el id de la llista
	si es el filtre d'ordenacions, s'afageix en el filtre el id de la llista*/
function aplicarFiltreLlistat(e, idThis, checkEdicio, checkOrdre) {
	if (checkEdicio) {
		filtres[0] = [];
		filtres[0][0] = idThis;
		if (idThis == 'ed|00|2020') {
			var i = 0;
			$('#edicions li').each(function() {
				filtres[0][i] = idThis;
				i++;
			});
		}
	}
	if (checkOrdre) {
		filtres[4] = idThis+"|0";
	}
	pagina = 1;
	paginaAnt = 1;
	nousCursos = 0;
	packs = 0;
	if (screenWidthCurs>=limitPantallaTablet)  {
		mostrarModalLoading();
		mostrarBlocCursos();
	}
};

function aplicarFiltres() {
	filtres[1]=[];
	filtres[2]=[];
	filtres[3]=[];
	filtres[5]=[0];
	/* Eliminem tots els checks dels filtres */
	$('.cnt-bloc-filtres label input:checked').each(function() {
		$(this).prop("checked", false);
	});
	mostrarBlocCursos();
}

