/* Versió ordinador i movil. Quan es clica un checkbox, aplica filtres */
function aplicarFiltreCheckbox(check, idThis) {
	var objThis = $('#'+idThis);
	if (screenWidthCurs>=limitPantallaTablet) mostrarModalLoading();
	if (check) {
		$("#filtres #" + idThis).prop("checked", true);
		$("#filtres-mobil #" + idThis).prop("checked", true);
		if (objThis.hasClass('hores'))
			filtres[1].push(objThis.val());
		else if (objThis.hasClass('temes'))
			filtres[2].push(objThis.val());
		else if (objThis.hasClass('nivells'))
			filtres[3].push(objThis.val());


		if ($('.cnt-bloc-filtres label input:checked').hasClass('altres'))
			filtres[5][0] = 1;
		else
			filtres[5][0] = 0;
	}
	else {
		$("#filtres #" + idThis).prop("checked", false);
		$("#filtres-mobil #" + idThis).prop("checked", false);

		if (objThis.hasClass('hores')) {
			var i = 0;
			while (i < filtres[1].length && filtres[1][i] != objThis.val()) i++;
			filtres[1].splice(i, 1);
		} else if (objThis.hasClass('temes')) {
			var i = 0;
			while (i < filtres[2].length && filtres[2][i] != objThis.val()) i++;
			filtres[2].splice(i, 1);
		} else if (objThis.hasClass('nivells')) {
			var i = 0;
			while (i < filtres[3].length && filtres[3][i] != objThis.val()) i++;
			filtres[3].splice(i, 1);
		}

		if ($('.cnt-bloc-filtres label input:checked').hasClass('altres'))
			filtres[5][0] = 1;
		else
			filtres[5][0] = 0;
	}
	pagina = 1;
	paginaAnt = 1;
	nousCursos = 0;
	packs = 0;

	mostrarBlocCursos();
};
/* Versió ordinador i movil. Quan es clica el botó d'eliminar filtres, elimina filters*/
function eliminarFiltres() {
	filtres = [[0], [], [], [], 'ordre|TITOL|ASC|1', [0]] //edicions, hores, temes, nivells, ordre
	// if (screenWidthCurs>=limitPantallaTablet)
	// 	mostrarModalLoading();

	/* Afegim les edicions disponibles en els filtres */
	var i = 0;
	$('#edicions li').each(function() {
		filtres[0][i] = $(this).attr('id');
		i++;
	});
	/* Eliminem tots els checks dels filtres */
	$('.cnt-bloc-filtres label input:checked').each(function() {
		$(this).prop("checked", false);
	});
	$('#ordre .element-selected').html('Ordena per');
	$('#edicions .element-selected').html("Selecciona l'edició");
	resetFiltres();
	if (screenWidthCurs>=limitPantallaTablet)
		mostrarBlocCursos();
};

function sticky() {
	var stickyBody = $('.sticky-body');
	var heightStickySideBar = $('.sticky-sidebar').css('height');
	var maxScrollTop = 0;
	$(window).scroll(function() { // scroll event
		if (screenWidthCurs > limitPantallaMovil) {
			$('.sticky-sidebar').css("height", stickyBody.css('height'));
			if (screenWidthCurs > limitPantallaTablet) //mida normal
				maxScrollTop = 1545.2;
			else //mida tablet
				maxScrollTop = 1857.6;

			if ((document.body.scrollTop > 0 || document.documentElement.scrollTop > maxScrollTop)) {
				var mida_top = 50;
			} else {
				$('.sticky-sidebar').css("height", stickyBody.css('height'));
			}
		}
	});
}

function canviPaginacio() {
	//cridarem la funció mostra els cursos amb filtres on FILTRES, pagina X, mida de la pantalla
	mostrarModalLoading();
	mostrarBlocCursos()
}

/* Retorna el valor val amb els punts de separacio*/
function pointSeparateNumber(val) {
	while (/(\d+)(\d{3})/.test(val.toString())) {
		val = val.toString().replace(/(\d+)(\d{3})/, '$1' + '.' + '$2');
	}
	return val;
}

function animateCounter(id, dataCount) {
	var counter = $('#'+id);
	var countTo = parseInt(dataCount);
	$({
		countNum: counter.text()
	}).animate({
		countNum: countTo
	}, {
		duration: 3500,
		easing: 'swing',
		step: function() {
			counter.text(pointSeparateNumber(Math.floor(this.countNum)));
		},
		complete: function() {
			counter.text(pointSeparateNumber(this.countNum));
		}
	});
}

